import { ENGINE_VERSION } from './engine.js';
import { demoBundle, validateConfig, analyzeBundle, summarizeRun, compareRuns, inspectImport, bundleChecksums, researchManifest, jsonDigest, runsCSV, MAX_IMPORT_BYTES, DEFAULT_CONFIG, DEFAULT_COMPARISON } from './research.js';
import { saveProject, listProjects, getProject, removeProject } from './projects.js';

let ui;
const state={bundle:demoBundle(),configs:[{...DEFAULT_CONFIG},{...DEFAULT_COMPARISON}],runs:null,busy:false,progress:0,error:'',dirty:false,observation:0,group:0,metric:'uor',page:0,expected:null,verification:'Synthetic input · reproducible fixture',projectList:null,projectError:'',worker:null,job:0,release:{},capture:{device:'cpu',tokens:1024,window:8,layers:'all',revision:'main',text:false}};
const f=(v,n=3)=>Number(v).toFixed(n),pct=v=>`${f(v*100,2)}%`;
const sourceLabels={synthetic:'Synthetic fixture',model_capture:'Model capture · importer declared',random_weight_model:'Random-weight model',imported:'Imported observations'};
const isV2=route=>['capture','explorer','compare','projects'].includes(route);
export const v2Routes={capture:'Capture a model',explorer:'Layer explorer',compare:'Compare experiments',projects:'Research projects'};

export function initializeV2(adapter){
  ui=adapter;
  fetch('./release.json').then(r=>r.ok?r.json():{}).then(r=>{state.release=r;}).catch(()=>{});
  document.addEventListener('click',async e=>{
    const button=e.target.closest('[data-v2]');if(!button)return;
    const action=button.dataset.v2;
    try {
      if(action==='import')document.querySelector('#v2-file').click();
      if(action==='demo'){state.bundle=demoBundle();state.runs=null;state.expected=null;state.observation=0;state.group=0;state.verification='Synthetic input · reproducible fixture';state.error='';state.dirty=false;runAnalysis(ui.route()==='compare'?state.configs:[state.configs[0]]);}
      if(action==='run'){state.expected=null;runAnalysis(ui.route()==='compare'?state.configs:[state.configs[0]]);}
      if(action==='cancel'){state.worker?.terminate();state.worker=null;state.busy=false;state.dirty=true;state.job++;state.error='Analysis canceled. Your input is unchanged.';ui.refresh();}
      if(action==='export'){if(state.dirty||!state.runs)throw new Error('Run the current configuration before exporting.');const manifest=await researchManifest(state.bundle,state.runs,state.release);ui.download('page-entrokv-research-v0.2.json',manifest);ui.toast('Complete manifest exported with inputs, results, and SHA-256 checksums.');}
      if(action==='csv'){if(state.dirty||!state.runs)throw new Error('Run the current configuration first.');ui.download('page-entrokv-selection-results.csv',runsCSV(state.runs),'text/csv;charset=utf-8');}
      if(action==='save')saveDialog();
      if(action==='sample')ui.download('page-entrokv-multilayer-synthetic.json',demoBundle());
      if(action==='smoke'){const response=await fetch('./assets/qwen2-smoke.json');if(!response.ok)throw new Error('The bundled capture example is unavailable.');await loadInput(await response.json());location.hash='/explorer';}
      if(action==='open-trace'){const observation=state.bundle.observations[state.observation];ui.openTrace(observation.trace,state.runs[0].config);}
      if(action==='inspect-page')pageInspector(Number(button.dataset.page));
      if(action==='copy-capture'){const c=state.capture;if(!Number.isInteger(c.tokens)||c.tokens<16||c.tokens>8192||!Number.isInteger(c.window)||c.window<1||c.window>32||!c.revision||!(/^(all|\d+(,\d+)*)$/.test(c.layers)))throw new Error('Complete valid capture settings before copying the command.');ui.copy(captureCommand());}
      if(action==='open-project'){const project=await getProject(button.dataset.id);if(!project)throw new Error('This project is no longer in local storage.');await loadInput(project);location.hash='/explorer';ui.toast('Full project opened and selections recomputed.');}
      if(action==='export-project'){const project=await getProject(button.dataset.id);if(!project)throw new Error('Project not found.');const {id,name,...manifest}=project;ui.download('page-entrokv-project.json',manifest);}
      if(action==='remove-project')removeDialog(button.dataset.id);
    } catch(error){ui.toast(error.message,'error');}
  });
}

export function renderV2(route){
  if(route==='capture')return captureView();
  if(route==='projects')return projectsView();
  return route==='compare'?compareView():explorerView();
}
const toolbar=()=>`<div class="v2-top-actions"><button class="button secondary" data-v2="import">${ui.icon('upload')} Import bundle</button><button class="button secondary" data-v2="export" ${state.busy||state.dirty||!state.runs?'disabled':''}>${ui.icon('download')} Full export</button><button class="button primary" data-v2="save" ${state.busy||state.dirty||!state.runs?'disabled':''}>${ui.icon('save')} Save project</button></div>`;
function sourceBanner(){
  const b=state.bundle,tokens=b.observations[0].trace.attention[0].length;
  return `<section class="v2-source card"><div class="v2-source-icon">${ui.icon(b.source==='model_capture'?'terminal':'layers')}</div><div class="v2-source-name"><strong>${ui.escape(b.name)}</strong><span>${b.observations.length} observations · ${tokens.toLocaleString()} token positions · ${ui.escape(b.metadata.model??'Unspecified model')}</span></div><span class="tag ${b.source==='synthetic'?'lavender-tag':'mint-tag'}">${sourceLabels[b.source]}</span><button class="button secondary v2-small" data-v2="demo">Use demo</button><input id="v2-file" type="file" accept=".json,application/json" hidden></section><div class="v2-integrity">${ui.icon('shield')} ${ui.escape(state.verification)}<span>Checksums verify content consistency; model provenance is not authenticated.</span></div>`;
}
function notice(){return `<div class="precision-strip">${ui.icon('info')}<span><strong>Observation analysis.</strong> Weighted and mean policies share the same group quota. Independent-head unions are an over-budget diagnostic. Attention mass is not answer accuracy.</span><a href="#/capture">Capture guide ${ui.icon('arrow')}</a></div>${state.error?`<div class="inline-error" role="alert">${ui.escape(state.error)}</div>`:''}`;}
function controls(label,index){
  const c=state.configs[index];
  return `<fieldset class="v2-config" ${state.busy?'disabled':''}><legend><span class="v2-config-label">${label}</span></legend><div class="v2-config-fields"><div><label for="v2-retention-${index}">Retention %</label><input id="v2-retention-${index}" data-v2-config="retention" data-config="${index}" type="number" min="0.01" max="100" step="any" value="${c.retention}"></div><div><label for="v2-block-${index}">Tokens / page</label><select id="v2-block-${index}" data-v2-config="blockSize" data-config="${index}">${[...new Set([4,8,16,32,64,128,c.blockSize])].sort((a,b)=>a-b).map(v=>`<option value="${v}" ${c.blockSize===v?'selected':''}>${v}</option>`).join('')}</select></div><div><label for="v2-tau-${index}">Temperature τ</label><input id="v2-tau-${index}" data-v2-config="tau" data-config="${index}" type="number" min="0.05" max="10" step="0.05" value="${c.tau}"></div><div><label for="v2-sink-${index}">Sink isolation</label><select id="v2-sink-${index}" data-v2-config="isolate" data-config="${index}"><option value="true" ${c.isolate?'selected':''}>On</option><option value="false" ${!c.isolate?'selected':''}>Off</option></select></div></div></fieldset>`;
}
function runBar(){return `<div class="v2-run-bar"><span id="v2-stale" ${state.dirty?'':'hidden'}>Settings changed. Run analysis to update results.</span><span class="v2-runtime-note">${ui.icon('lock')} Local computation · Float64 · deterministic page ties</span>${state.busy?`<span class="v2-progress" role="status">Computing <span id="v2-progress">${Math.round(state.progress*100)}</span>%</span><button class="button secondary" data-v2="cancel">Cancel</button>`:`<button class="button primary" data-v2="run">${ui.icon('flask')} ${state.runs?'Recompute selections':'Compute selections'} ${ui.icon('arrow')}</button>`}</div>`;}
function loading(){return `<div class="v2-loading card"><span class="v2-loader" aria-hidden="true"></span><h2>${state.busy?'Computing across observations…':'Ready for your next question.'}</h2><p>${state.busy?'The analysis runs in a background worker. You can cancel without losing your input.':'Set a configuration and compute the selection.'}</p></div>`;}

function explorerView(){
  return `${ui.heading('V0.2 · REAL INPUTS, VISIBLE ASSUMPTIONS.','Follow the signal, layer by layer.','Import model observations. Inspect every group. Preserve the full experiment.',toolbar())}<div class="v2">${notice()}${sourceBanner()}<section class="card v2-control-card">${controls('Selection configuration',0)}${runBar()}</section>${state.runs?`<div class="v2-results ${state.dirty?'v2-outdated':''}">${heatmap()}${groupDetail()}</div>`:loading()}<div class="v2-bottom-links"><a class="text-link" href="#/capture">${ui.icon('terminal')} Capture your first real model observation</a><a class="text-link" href="#/compare">Compare two configurations ${ui.icon('arrow')}</a></div></div>`;
}
function metricValue(group){if(state.metric==='mass')return {value:group.metrics.weighted.reference_mass,text:pct(group.metrics.weighted.reference_mass)};if(state.metric==='agreement')return {value:group.weighted_mean_jaccard,text:pct(group.weighted_mean_jaccard)};return {value:Math.min(group.uor/6,1),text:`${f(group.uor,2)}×`};}
function heatmap(){
  const run=state.runs[0],columns=Math.max(...run.observations.map(o=>o.groups.length));
  return `<section class="card v2-layer-card"><div class="card-heading"><div><span class="eyebrow">THE WHOLE OBSERVATION SET</span><h2>Layer × KV group</h2><p>Select a cell to inspect its heads, pages, and token positions.</p></div><div><label for="v2-metric">Cell metric</label><select id="v2-metric"><option value="uor" ${state.metric==='uor'?'selected':''}>Independent union overhead</option><option value="mass" ${state.metric==='mass'?'selected':''}>Weighted: head-mean mass</option><option value="agreement" ${state.metric==='agreement'?'selected':''}>Weighted / mean agreement</option></select></div></div><div class="v2-heatmap-scroll"><table class="v2-heatmap"><thead><tr><th>Observation</th>${Array.from({length:columns},(_,g)=>`<th>KV ${g}</th>`).join('')}</tr></thead><tbody>${run.observations.map((o,i)=>`<tr><th scope="row">Layer ${o.layer}<small>${ui.escape(o.id)}</small></th>${Array.from({length:columns},(_,g)=>{const group=o.groups[g];if(!group)return'<td>—</td>';const metric=metricValue(group);return `<td><button class="v2-heatcell ${i===state.observation&&g===state.group?'selected':''}" data-observation="${i}" data-group="${g}" style="--cell-alpha:${.07+metric.value*.30}" aria-label="Layer ${o.layer}, observation ${ui.escape(o.id)}, KV group ${g}, ${metric.text}" aria-pressed="${i===state.observation&&g===state.group}">${metric.text}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table></div><div class="table-foot">${state.metric==='uor'?'Union of each sibling head’s K-page selection, divided by K. This can exceed the shared group quota.':state.metric==='mass'?'Retained mass under the arithmetic mean of original sibling attention rows. Same reference across policies; not task accuracy.':'Jaccard overlap of retained token positions for entropy-weighted and arithmetic-mean pooling.'} Captured layers only; no claim about unobserved layers.</div></section>`;
}
function groupDetail(){
  const observation=state.runs[0].observations[state.observation],group=observation.groups[state.group],a=state.configs[0];
  const actual=state.runs[0].config,selected=new Set(group.selected),mean=new Set(group.meanSelected),max=Math.max(...group.scores),ratio=state.bundle.observations[state.observation].trace.query_heads/observation.groups.length;
  return `<section class="v2-inspection"><div class="card v2-group-map"><div class="card-heading"><div><span class="eyebrow">SELECTED OBSERVATION</span><h2>Layer ${observation.layer} · KV group ${state.group}</h2><p>${observation.quota} / ${observation.pages} pages · ${f(observation.realizedRetention,3)}% after rounding · ${actual.blockSize} tokens/page</p></div><button class="button secondary v2-small" data-v2="open-trace">Single-layer tool ${ui.icon('arrow')}</button></div><div class="v2-policy-key"><span><i class="v2-dot weighted"></i> Both policies</span><span><i class="v2-dot weighted-only"></i> Weighted only</span><span><i class="v2-dot mean-only"></i> Mean only</span><span><i class="v2-dot"></i> Neither</span></div><div class="page-grid v2-selection-grid" style="--columns:16">${group.scores.map((score,p)=>`<button class="page-cell ${selected.has(p)&&mean.has(p)?'v2-both':selected.has(p)?'v2-weighted':mean.has(p)?'v2-mean':''}" data-v2="inspect-page" data-page="${p}" aria-label="Inspect page ${p}, ${selected.has(p)?'weighted retained':'weighted evicted'}, ${mean.has(p)?'mean retained':'mean evicted'}"><span>${p}</span></button>`).join('')}</div><div class="v2-policy-summary">${[['Weighted',group.metrics.weighted],['Mean',group.metrics.mean],['Independent union',group.metrics.independent]].map(([name,m])=>`<div><span>${name}</span><strong>${m.pages} pages</strong><small>${pct(m.reference_mass)} head-mean mass</small></div>`).join('')}</div><div class="table-foot">Agreement: ${pct(group.weighted_mean_jaccard)} token Jaccard. Independent union is a diagnostic, not an equal-budget baseline.</div></div><div class="card v2-head-weights"><div class="card-heading"><div><h2>The heads behind the choice</h2><p>Sink-isolated entropy ${actual.isolate?'on':'off'} · τ ${actual.tau}</p></div></div><table><thead><tr><th>Head</th><th>H₂, nats</th><th>Weight</th></tr></thead><tbody>${group.weights.map((w,h)=>`<tr><td>H${state.group*ratio+h}</td><td class="mono">${f(group.entropies[h],5)}</td><td class="mono">${f(w*100,4)}%</td></tr>`).join('')}</tbody></table><div class="table-foot">Lower entropy increases weight. It does not independently establish relevance.</div></div></section>`;
}
function pageInspector(page){
  const o=state.runs[0].observations[state.observation],g=o.groups[state.group],c=state.runs[0].config,b=state.bundle;
  const start=page*c.blockSize,end=Math.min((page+1)*c.blockSize,o.tokens);
  ui.showDialog(`<span class="eyebrow">LAYER ${o.layer} · KV ${state.group} · PAGE ${page}</span><h2 id="detail-title">Inspect the original positions.</h2><p class="dialog-description">Tokens ${start}–${end-1}, zero-indexed. ${g.selected.includes(page)?'Weighted retained.':'Weighted evicted.'} ${g.meanSelected.includes(page)?'Mean retained.':'Mean evicted.'}</p><div class="detail-metrics"><div><span>Weighted max score</span><strong class="mono">${g.scores[page].toExponential(5)}</strong></div><div><span>Mean max score</span><strong class="mono">${g.meanScores[page].toExponential(5)}</strong></div></div><table class="v2-token-table"><thead><tr><th>Position</th><th>Token ID</th><th>Decoded token, if included</th></tr></thead><tbody>${Array.from({length:end-start},(_,i)=>{const t=start+i;return `<tr><td class="mono">${t}</td><td class="mono">${b.token_ids?.[t]??'—'}</td><td><code>${b.token_text?ui.escape(b.token_text[t]):'Not included'}</code></td></tr>`;}).join('')}</tbody></table><div class="doc-callout">${ui.icon('lock')} Token text is optional and may contain private prompt content. It stays in the imported bundle and is included in full exports.</div>`);
}

function compareView(){
  return `${ui.heading('V0.2 · ONE INPUT, TWO QUESTIONS.','Compare decisions, not impressions.','Change the budget, temperature, or page size. Inspect the difference.',toolbar())}<div class="v2">${notice()}${sourceBanner()}<section class="card v2-control-card"><div class="v2-config-pair">${controls('Configuration A',0)}${controls('Configuration B',1)}</div>${runBar()}</section>${state.runs?.length>=2?`<div class="v2-results ${state.dirty?'v2-outdated':''}">${comparisonResults()}</div>`:loading()}</div>`;
}
function aggregate(run,policy){const groups=run.observations.flatMap(o=>o.groups.map(g=>g.metrics[policy]));return {retention:groups.reduce((s,g)=>s+g.realized_retention,0)/groups.length,mass:groups.reduce((s,g)=>s+g.reference_mass,0)/groups.length};}
function comparisonResults(){
  const [a,b]=state.runs,rows=compareRuns(a,b),meanJ=rows.reduce((s,r)=>s+r.jaccard,0)/rows.length;
  const points=[['A · weighted',aggregate(a,'weighted'),'#6c4da2'],['A · mean',aggregate(a,'mean'),'#3e7658'],['B · weighted',aggregate(b,'weighted'),'#b28bcf'],['B · mean',aggregate(b,'mean'),'#b77542']];
  return `<div class="v2-comparison-summary"><div class="card"><span>Token overlap · A vs B</span><strong>${pct(meanJ)}</strong><small>Mean Jaccard across observed layer–group pairs</small></div><div class="card"><span>Compared observations</span><strong>${rows.length}</strong><small>${state.bundle.observations.length} layer observations · matched input</small></div><div class="card"><span>What changed?</span><div class="v2-diff">${Object.keys(a.config).filter(k=>a.config[k]!==b.config[k]).map(k=>`<span>${k}: <b>${a.config[k]}</b> → <b>${b.config[k]}</b></span>`).join('')||'<span>Configurations are identical.</span>'}</div></div></div><div class="v2-compare-grid"><section class="card v2-plot"><div class="card-heading"><div><h2>Attention mass vs page budget</h2><p>Each marker is a computed policy/configuration.</p></div><button class="button secondary v2-small" data-v2="csv">${ui.icon('download')} CSV</button></div><svg viewBox="0 0 520 310" role="img" aria-label="Comparison of realized page retention and retained head-mean attention mass"><g fill="none" stroke="#e9e3dc">${[0,25,50,75,100].map(t=>`<path d="M60 ${250-t*2.05}H485"/><path d="M${60+t*4.25} 45V250"/>`).join('')}</g><g fill="#776c5c" font-family="system-ui" font-size="10">${[0,25,50,75,100].map(t=>`<text x="48" y="${254-t*2.05}" text-anchor="end">${t}%</text><text x="${60+t*4.25}" y="270" text-anchor="middle">${t}%</text>`).join('')}<text x="275" y="299" text-anchor="middle">Realized retained page capacity</text><text transform="translate(14 155) rotate(-90)" text-anchor="middle">Retained head-mean attention mass</text></g>${points.map(([label,p,color],i)=>`<circle cx="${60+p.retention*4.25}" cy="${250-p.mass*205}" r="${i<2?7:5}" fill="${color}" stroke="white" stroke-width="2"><title>${label}: ${f(p.retention,3)}% pages; ${pct(p.mass)} mass</title></circle>`).join('')}</svg><div class="v2-plot-legend">${points.map(([label,p,color])=>`<span><i style="background:${color}"></i>${label} <b>${pct(p.mass)}</b></span>`).join('')}</div><div class="table-foot">Equal weight per observed layer–group pair. Same head-mean reference for both policies. This plot does not measure quality, GPU memory, or throughput.</div></section><section class="card v2-comparison-notes"><span class="note-icon">${ui.icon('shield')}</span><h2>A fair question needs a stated budget.</h2><p>Within each configuration, weighted and mean pooling retain exactly the same number of pages per group.</p><p>If A and B use different page sizes, overlap is computed over valid original token positions—not page indices.</p><p>The independent-head union may exceed the quota. Its rows are labeled separately in CSV exports.</p><a class="text-link" href="#/explorer">Inspect individual observations ${ui.icon('arrow')}</a></section></div><section class="card v2-comparison-table table-scroll"><table><thead><tr><th>Observation</th><th>KV group</th><th>A · pages</th><th>B · pages</th><th>A · head-mean mass</th><th>B · head-mean mass</th><th>Token Jaccard</th></tr></thead><tbody>${rows.map(r=>`<tr><td>Layer ${r.layer}<small>${ui.escape(r.observation)}</small></td><td class="mono">${r.group}</td><td class="mono">${r.a_pages}</td><td class="mono">${r.b_pages}</td><td class="mono">${pct(r.a_mass)}</td><td class="mono">${pct(r.b_mass)}</td><td class="mono">${pct(r.jaccard)}</td></tr>`).join('')}</tbody></table></section>`;
}

function captureCommand(){const c=state.capture;return `python dist/assets/capture_attention.py \\\n  --model Qwen/Qwen2.5-1.5B-Instruct \\\n  --revision ${c.revision||'main'} \\\n  --prompt-file prompt.txt --output capture.json \\\n  --device ${c.device} --dtype ${c.device==='cpu'?'float32':'bfloat16'} \\\n  --max-tokens ${c.tokens} --observation-window ${c.window} \\\n  --layers ${c.layers||'all'}${c.text?' \\\n  --include-token-text':''}`;}
function captureView(){
  const c=state.capture;
  return `${ui.heading('V0.2 · YOUR MODEL. YOUR HARDWARE.','Bring a real observation to the table.','Capture bounded Qwen2 attention locally, then inspect it here.',`<a class="button primary" href="./assets/capture_attention.py" download>${ui.icon('download')} Capture script</a>`)}<div class="v2"><div class="v2-capture-hero"><div><span class="eyebrow">A SMALL, REPRODUCIBLE PATH</span><h2>Capture locally.<br>Explore together.</h2><p>Prefill the context with SDPA, then collect only the final query window with eager attention. Export selected layers as a validated, checksummed bundle.</p><div class="v2-capture-chips"><span>Qwen2.5 · 1.5B</span><span>CPU or CUDA</span><span>Offline analysis</span></div></div><img src="./assets/folio.webp" width="220" height="220" alt="Folio organizing model observations."></div><div class="v2-capture-layout"><section class="card v2-capture-setup"><div class="card-heading"><h2>1. Set up the capture</h2>${ui.icon('terminal')}</div><label for="capture-device">Execution device</label><select id="capture-device" data-capture="device"><option value="cpu" ${c.device==='cpu'?'selected':''}>CPU · float32 · higher RAM use</option><option value="cuda" ${c.device==='cuda'?'selected':''}>CUDA · bfloat16 · GPU required</option></select><div class="form-grid"><div><label for="capture-tokens">Maximum context tokens</label><input id="capture-tokens" data-capture="tokens" type="number" min="16" max="8192" value="${c.tokens}"></div><div><label for="capture-window">Query window</label><input id="capture-window" data-capture="window" type="number" min="1" max="32" value="${c.window}"></div></div><label for="capture-layers">Layers</label><input id="capture-layers" data-capture="layers" value="${ui.escape(c.layers)}" placeholder="all, or 0,7,14,21,27"><label for="capture-revision">Model revision</label><input id="capture-revision" data-capture="revision" value="${ui.escape(c.revision)}" placeholder="Prefer an immutable commit SHA"><p class="field-help">The model and tokenizer use the same requested revision. Resolved revisions are recorded when available. A moving “main” revision is not an immutable specification.</p><label class="v2-checkbox"><input type="checkbox" id="capture-text" data-capture="text" ${c.text?'checked':''}> Include decoded token text in the export</label><p class="field-help">Optional token text may contain private prompt content. Token IDs are included by default. Your model and prompt are never uploaded by this site.</p></section><section class="card v2-capture-command"><div class="card-heading"><h2>2. Run on your machine</h2><button class="button secondary v2-small" data-v2="copy-capture">${ui.icon('code')} Copy command</button></div><div class="code-header"><span>One-time setup · cloned repository</span></div><pre>python -m venv .venv\n# Activate .venv for your operating system\npython -m pip install -r dist/assets/requirements-capture.txt</pre><div class="v2-install-note">For CPU-only PyTorch, first install <code>torch==2.8.0</code> from the official CPU wheel index. CUDA users need a matching PyTorch installation. Full model weights require a separate download and sufficient RAM/VRAM.</div><pre id="capture-command">${ui.escape(captureCommand())}</pre><p>Save a UTF-8 <code>prompt.txt</code> with at least 16 tokens. The script refuses to overwrite an existing capture file.</p><div class="doc-actions"><a class="button secondary" href="./assets/requirements-capture.txt" download>Requirements</a><a class="button secondary" href="./assets/example-prompt.txt" download>Example prompt</a></div><div class="v2-smoke"><strong>Check the pipeline without downloading weights</strong><code>python dist/assets/capture_attention.py --smoke-test --output smoke.json</code><span>Runs a tiny random-weight Qwen2 on CPU. Output is explicitly labeled; it is not a pretrained-model benchmark.</span><button class="button secondary v2-small" data-v2="smoke">Open captured example ${ui.icon('arrow')}</button></div></section></div><section class="v2-import-cta"><span class="v2-step-number">3</span><div><h2>Open the bundle in Layer Explorer.</h2><p>Import capture.json, inspect layers and groups, compare configurations, then save or export the full record.</p></div><a class="button primary" href="#/explorer">Open Layer Explorer ${ui.icon('arrow')}</a></section><section class="card v2-capture-contract"><h2>The capture contract</h2><div class="v2-contract-grid"><div><h3>Bounded observations</h3><p>One unpadded prompt, 16–8,192 context tokens, 1–32 final query rows, and at most 1,048,576 exported attention values. Temporary attention storage is also bounded.</p></div><div><h3>Explicit normalization</h3><p>Cast attention rows are averaged and normalized in Float64. Original row-sum errors and the transformation are recorded. The browser never silently renormalizes imports.</p></div><div><h3>Honest scope</h3><p>No generation-quality claim, no cache eviction during model execution, and no vLLM integration. The sampled final-query window is not an observation of future queries.</p></div></div><div class="v2-capture-links"><a class="text-link" href="https://huggingface.co/docs/transformers/attention_interface" target="_blank" rel="noopener noreferrer">Transformers attention interface ${ui.icon('external')}</a><a class="text-link" href="https://github.com/bruce12-glitch/Powered-EntroKV-/blob/main/dist/assets/capture_attention.py" target="_blank" rel="noopener noreferrer">Inspect the capture source ${ui.icon('github')}</a></div></section></div>`;
}

function projectsView(){
  return `${ui.heading('V0.2 · THE WHOLE EXPERIMENT, KEPT.','Your research projects.','Complete inputs and configuration records, saved on this browser.',`<a class="button secondary" href="#/experiments">v0.1 snapshots</a><a class="button primary" href="#/explorer">${ui.icon('plus')} New project</a>`)}<div class="v2">${state.projectError?`<div class="inline-error" role="alert">${ui.escape(state.projectError)}</div>`:''}<div class="v2-project-note">${ui.icon('lock')} Full observations are stored locally using IndexedDB only when you choose Save project. Browser data can be cleared; keep a downloaded manifest for durable research records.</div>${state.projectList===null?'<div class="v2-loading card"><span class="v2-loader"></span><p>Opening the local project library…</p></div>':state.projectList.length?`<section class="v2-project-grid">${state.projectList.map(p=>`<article class="card v2-project"><div class="v2-project-top"><span class="note-icon lavender">${ui.icon('folder')}</span><span class="tag lavender-tag">${sourceLabels[p.source]??'Imported'}</span></div><h2>${ui.escape(p.name)}</h2><p>${p.observations} observations · ${p.configurations} configurations</p><span class="v2-project-date">${new Date(p.created_at).toLocaleString()}</span><div class="v2-project-actions"><button class="button primary" data-v2="open-project" data-id="${ui.escape(p.id)}">Open project ${ui.icon('arrow')}</button><button class="icon-button" data-v2="export-project" data-id="${ui.escape(p.id)}" aria-label="Export ${ui.escape(p.name)}">${ui.icon('download')}</button><button class="icon-button danger" data-v2="remove-project" data-id="${ui.escape(p.id)}" aria-label="Remove ${ui.escape(p.name)}">${ui.icon('trash')}</button></div></article>`).join('')}</section>`:`<section class="empty-notebook card"><div class="empty-art"><img src="./assets/folio.webp" width="200" height="200" alt="Folio holding the next research project."></div><span class="eyebrow">A COMPLETE RECORD STARTS HERE</span><h2>Keep the inputs, too.</h2><p>Analyze a bundle, then save the full project.<br>Reopen it later and recompute every selection.</p><a class="button primary" href="#/explorer">Start an experiment ${ui.icon('arrow')}</a></section>`}</div>`;
}

export function bindV2(route){
  if(!isV2(route))return;
  document.querySelector('#v2-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>MAX_IMPORT_BYTES)throw new Error('Import exceeds the 32 MiB limit.');let raw;try{raw=JSON.parse(await file.text());}catch{throw new Error('The file is not valid JSON.');}await loadInput(raw);}catch(error){state.error=error.message;ui.refresh();ui.toast(error.message,'error');}});
  document.querySelectorAll('[data-v2-config]').forEach(el=>el.addEventListener('input',e=>{const key=el.dataset.v2Config;state.configs[+el.dataset.config][key]=key==='isolate'?el.value==='true':+el.value;state.dirty=true;state.expected=null;document.querySelector('#v2-stale').hidden=false;document.querySelectorAll('[data-v2="export"],[data-v2="save"],[data-v2="csv"]').forEach(b=>b.disabled=true);document.querySelector('.v2-results')?.classList.add('v2-outdated');}));
  document.querySelector('#v2-metric')?.addEventListener('change',e=>{state.metric=e.target.value;ui.refresh();});
  document.querySelectorAll('[data-observation]').forEach(button=>button.addEventListener('click',()=>{state.observation=+button.dataset.observation;state.group=+button.dataset.group;ui.refresh();document.querySelector('.v2-inspection')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}));
  document.querySelectorAll('[data-capture]').forEach(el=>el.addEventListener('input',()=>{const key=el.dataset.capture;let value=el.type==='checkbox'?el.checked:el.type==='number'?+el.value:el.value;if(key==='revision')value=value.replace(/[^A-Za-z0-9_./-]/g,'');if(key==='layers')value=value.replace(/[^a-zA-Z0-9,]/g,'');state.capture[key]=value;document.querySelector('#capture-command').textContent=captureCommand();}));
  if(route==='projects'&&state.projectList===null)refreshProjects();
  if((route==='explorer'||route==='compare')&&!state.busy&&!state.runs&&!state.dirty&&!state.error)runAnalysis(route==='compare'?state.configs:[state.configs[0]]);
}
async function loadInput(raw){
  state.worker?.terminate();state.worker=null;const loadId=++state.job;state.busy=true;state.error='';ui.refresh();
  try {
    const loaded=await inspectImport(raw),checksums=await bundleChecksums(loaded.bundle);
    if(loadId!==state.job)return;
    state.bundle=loaded.bundle;state.observation=0;state.group=0;state.runs=null;state.error='';state.dirty=false;state.expected=loaded.expected;
    if(loaded.configs){state.configs[0]=loaded.configs[0];state.configs[1]=loaded.configs[1]??{...DEFAULT_COMPARISON};}
    state.verification=`${loaded.expected?'Manifest input and stored-result checksums verified':'Attention checksums computed'} · SHA-256 ${checksums.bundle_sha256.slice(0,12)}…`;
    state.busy=false;runAnalysis(loaded.configs??(ui.route()==='compare'?state.configs:[state.configs[0]]));
  } catch(error){if(loadId===state.job){state.busy=false;state.dirty=true;state.error=error.message;ui.refresh();}throw error;}
}
export async function importResearchFile(raw){await loadInput(raw);location.hash='/explorer';}
export async function exportSingleObservation(trace,config){try{const bundle=(await inspectImport(trace)).bundle;const run=analyzeBundle(bundle,config);ui.download('page-entrokv-observation-v0.2.json',await researchManifest(bundle,[run],state.release));ui.toast('Single observation exported with SHA-256 checksums.');}catch(error){ui.toast(error.message,'error');}}
function runAnalysis(rawConfigs){
  try {
    const configs=rawConfigs.map(validateConfig);
    state.worker?.terminate();const id=++state.job;
    state.worker=new Worker(new URL('./analysis-worker.js',import.meta.url),{type:'module'});
    state.busy=true;state.progress=0;state.error='';ui.refresh();
    state.worker.onmessage=async event=>{
      if(event.data.id!==state.job)return;
      if(event.data.progress!==undefined){state.progress=event.data.progress;const label=document.querySelector('#v2-progress');if(label)label.textContent=String(Math.round(state.progress*100));return;}
      state.worker?.terminate();state.worker=null;
      if(event.data.error){state.busy=false;state.error=event.data.error;ui.refresh();return;}
      const completed=event.data.runs,expected=state.expected;
      if(expected){try{const digest=await jsonDigest(completed.map(summarizeRun));if(id!==state.job)return;state.verification=digest===expected.results_sha256?`Recomputed results match the imported manifest · engine ${expected.engine_version}`:`Recomputed results differ from imported engine ${expected.engine_version}. Inspect before using.`;}catch(error){if(id!==state.job)return;state.error=error.message;}}
      if(id!==state.job)return;
      state.runs=completed;state.dirty=false;state.busy=false;ui.refresh();
    };
    state.worker.onerror=()=>{if(id!==state.job)return;state.worker?.terminate();state.worker=null;state.busy=false;state.error='The analysis worker could not complete. Reduce the bundle size or reload the workspace.';ui.refresh();};
    state.worker.postMessage({id,bundle:state.bundle,configs});
  } catch(error){state.error=error.message;state.busy=false;ui.refresh();}
}
async function refreshProjects(){try{state.projectList=await listProjects();state.projectError='';}catch(error){state.projectList=[];state.projectError=error.message;}if(ui.route()==='projects')ui.refresh();}
function saveDialog(){
  if(!state.runs||state.dirty)throw new Error('Compute the current selection first.');
  ui.showDialog(`<span class="eyebrow">V0.2 · INPUTS INCLUDED</span><h2 id="detail-title">Save a complete project.</h2><p class="dialog-description">Store this bundle and its configuration on this browser. Full attention arrays and optional token text are included.</p><form id="v2-save-form"><label for="v2-project-name">Project name</label><input id="v2-project-name" value="${ui.escape(state.bundle.name)}" maxlength="120" required><p class="field-help">Keep a downloaded full export as well. Browser storage is not a durable backup.</p><button class="button primary full" type="submit">${ui.icon('save')} Save full project</button></form>`);
  document.querySelector('#v2-save-form').onsubmit=async e=>{e.preventDefault();const name=document.querySelector('#v2-project-name').value.trim();if(!name)return;const button=e.target.querySelector('button');button.disabled=true;button.textContent='Verifying and saving…';try{const manifest=await researchManifest(state.bundle,state.runs,state.release);const id=crypto.randomUUID?.()??[...crypto.getRandomValues(new Uint32Array(4))].join('-');await saveProject({...manifest,id,name});state.projectList=null;document.querySelector('#detail-dialog').close();ui.toast('Complete project saved locally, including all observations.');}catch(error){button.disabled=false;button.textContent='Try saving again';ui.toast(error.message,'error');}};
}
function removeDialog(id){
  const p=state.projectList?.find(p=>p.id===id);if(!p)return;
  ui.showDialog(`<span class="eyebrow">REMOVE LOCAL PROJECT</span><h2 id="detail-title">Remove “${ui.escape(p.name)}”?</h2><p class="dialog-description">This removes the complete local input and configuration record. A downloaded manifest can be imported again.</p><div class="doc-actions"><button class="button secondary" data-action="close-detail">Keep project</button><button class="button danger-button" id="v2-confirm-remove">Remove local project</button></div>`);
  document.querySelector('#v2-confirm-remove').onclick=async()=>{try{await removeProject(id);document.querySelector('#detail-dialog').close();state.projectList=null;await refreshProjects();ui.toast('Local project removed. Downloaded manifests are unchanged.');}catch(error){ui.toast(error.message,'error');}};
}
